import{z as i,x as n,o as t,c as B,q as E,j as r,D as e,d as s,s as A,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"STaR Self-Taught Reasoner","description":"","frontmatter":{"title":"STaR Self-Taught Reasoner","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/star-reasoner.md","filePath":"llm/star-reasoner.md","lastUpdated":1791063341000}'),h={name:"llm/star-reasoner.md"};function p(T,a,d,C,S,R){const o=n("Mermaid");return t(),B("div",null,[a[2]||(a[2]=E('<h1 id="star-self-taught-reasoner" tabindex="-1">STaR Self-Taught Reasoner <a class="header-anchor" href="#star-self-taught-reasoner" aria-label="Permalink to &quot;STaR Self-Taught Reasoner&quot;">​</a></h1><div class="epigraph"><p>用少量带理由的例子去生成许多理由，只保留能推出正确答案的那些，再微调；错的题目则把答案当作提示，让模型反过来写一条能通向该答案的理由。</p><footer>—— Zelikman, Wu, Mu, Goodman，STaR: Bootstrapping Reasoning With Reasoning，NeurIPS 2022</footer></div><p>思维链能提高算术、常识与应用题成绩，但完整理由标注贵，纯 few-shot 又不改权重。Zelikman 等人提出 Self-Taught Reasoner（STaR）：外环在「生成 → 按答案过滤 → 微调」之间打转，把一小撮示范扩成越来越大的自生成理由集。做不对的题不是丢掉，而是<strong>合理化</strong>（rationalization）——把正确答案塞进提示，让模型倒着写理由，微调时再把答案提示拿掉。本篇按 arXiv:2203.14465 写循环、合理化与 GPT-J 上的数字；token 级默想见 <a href="/llm/quiet-star">Quiet-STaR</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>当时诱导理由有两条路。一条是人工写成千上万条逐步解答再监督微调，贵，且理由风格被标注者锁死。另一条是 Wei 等人的 few-shot chain-of-thought：推理时在提示里放几条示范，权重大不变，难题上 6B 级模型几乎帮不上。需要一种中间物：示范很少，无理由的题很多，模型用自己的生成当训练数据，并且难度能随外环上升。</p><p>只保留「答对了的理由」会停在模型已经会的题上——外环饱和。错题若直接拿来训，又会强化坏推理。STaR 要解决的是：如何从失败里得到<strong>仍能导向正确答案</strong>的理由，而不把「高温度蒙对」当成正例。后者在算术上尤其致命：温度一升高，草稿纸与答案脱节，模型会学到无意义中间步骤。</p><h3 id="自举的前提是-few-shot-高于随机" tabindex="-1">自举的前提是 few-shot 高于随机 <a class="header-anchor" href="#自举的前提是-few-shot-高于随机" aria-label="Permalink to &quot;自举的前提是 few-shot 高于随机&quot;">​</a></h3><p>外环第一步必须能采样到一些对的理由。作者发现 GPT-2 在算术上无法从 few-shot 起步；GPT-J 6B 可以。二分类、正确率接近随机的任务会混进大量「理由胡写、选项碰巧对」的样本，过滤器失效。这是方法边界，不是调参能消掉的。</p><p><span class="marginnote">合理化不是把标准答案泄漏进部署。训练时提示含 \\(y\\)，写入数据集时只留 \\((x,r,y)\\)，推理与下一轮生成都不给 \\(y\\)。若实现忘了删提示，模型学会的是抄答案而不是推理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记少量带理由示范为 \\(P\\)，无理由但有标签的题集为 \\(D\\)。每一外环：</p><ol><li>用 \\(P\\) 作 few-shot，对 \\(D\\) 中的 \\(x\\) 采样理由 \\(\\hat r\\) 与答案 \\(\\hat y\\)。</li><li>若 \\(\\hat y=y\\)，把 \\((x,\\hat r,y)\\) 加入本轮训练集。</li><li>对失败题，把 \\(y\\) 作为提示再采样理由（合理化）；若新理由能重新推出 \\(y\\)，同样收入。</li><li>从<strong>原始预训练检查点</strong>（或固定起点）微调，而不是在上一外环权重上接着训——避免一次过拟合锁死。步数随外环增加（原文：首轮 40 step，之后每轮约 +20%）。</li><li>用新模型重复。算术上他们在第 30 轮后截断训练集规模以免过长。</li></ol><p>微调阶段把少量 few-shot 示范混进批次，作者消融认为这对 CQA 有帮助（无合理化从 60.9% 到 68.8%，有合理化从 69.9% 到 72.5%）。</p><p><span class="marginnote">「外环」就是「采样一批 → 按答案过滤 → 重新微调」这一整圈跑一遍的代称。可以想象成学生每做完一轮题，就把自己做对的解答整理成新讲义，再从原始课本（基座权重）出发重新学一遍——讲义每轮都在变厚变好，但起点每次都重置回课本，防止一轮学歪后步步歪。</span></p><p>主实验基座 GPT-J。算术：5 万随机加减题，外环每轮抽 1 万；16 轮后总体准确率 89.5%，对照「1 万无理由样本训 5000 step」为 76.3%，few-shot 即使带草稿纸在 2 位数上已 \\(\\lt 1\\%\\)。CommonsenseQA：STaR+合理化 72.5%，GPT-J 直接微调 60.0%，few-shot CoT 36.6%；文中写与约 30 倍大的 GPT-3 直接微调（73%）接近。GSM8K：STaR+合理化 10.7%，直接微调 5.8%，few-shot CoT 约 3%；合理化在 GSM8K 上增益不大。最终 CQA 模型用到训练集约 78.2% 的生成理由，另加约 8.5% 来自合理化。</p>',15)),(t(),r(l,null,{default:e(()=>[A(o,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%B0%91%E9%87%8F%E5%B8%A6%E7%90%86%E7%94%B1%E7%A4%BA%E8%8C%83%22%5D%20--%3E%20GEN%5B%22%E5%AF%B9%20D%20%E9%87%87%E6%A0%B7%20r%CC%82%2C%20%C5%B7%22%5D%0A%20%20GEN%20--%3E%20OK%7B%22%C5%B7%20%3D%20y%3F%22%7D%0A%20%20OK%20--%3E%7C%E6%98%AF%7C%20POS%5B%22%E6%94%B6%E5%85%A5%20(x%2C%20r%CC%82%2C%20y)%22%5D%0A%20%20OK%20--%3E%7C%E5%90%A6%7C%20RAT%5B%22%E6%8F%90%E7%A4%BA%E9%87%8C%E5%8A%A0%E5%85%A5%20y%EF%BC%8C%E5%86%8D%E5%86%99%E7%90%86%E7%94%B1%22%5D%0A%20%20RAT%20--%3E%20OK2%7B%22%E8%83%BD%E6%8E%A8%E5%87%BA%20y%3F%22%7D%0A%20%20OK2%20--%3E%7C%E6%98%AF%7C%20POS%0A%20%20POS%20--%3E%20FT%5B%22%E4%BB%8E%E5%9F%BA%E5%BA%A7%E5%BE%AE%E8%B0%83%22%5D%0A%20%20FT%20--%3E%20NEW%5B%22%E6%96%B0%E7%AD%96%E7%95%A5%EF%BC%8C%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E5%A4%96%E7%8E%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h3 id="合理化为何不是高温度" tabindex="-1">合理化为何不是高温度 <a class="header-anchor" href="#合理化为何不是高温度" aria-label="Permalink to &quot;合理化为何不是高温度&quot;">​</a></h3><p>高温度增加「答案对、理由错」的比例，算术草稿纸会崩成乱码，外环停滞。合理化条件在 \\(y\\) 上，模型做的是逆向：已知目标，填一条前向看起来合法的链。过滤仍然要「这条链推出的答案等于 \\(y\\)」，不是有了 \\(y\\) 就无条件收录。作者把高温度对照写成系统更差，且生成是序列瓶颈，多采样比再跑一次带答案的前向更贵。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="过滤把推理当隐变量" tabindex="-1">过滤把推理当隐变量 <a class="header-anchor" href="#过滤把推理当隐变量" aria-label="Permalink to &quot;过滤把推理当隐变量&quot;">​</a></h3><p>真正的目标是 \\(p(y\\mid x)\\)，理由 \\(r\\) 是帮助计算它的隐轨迹。STaR 用指示函数 \\(\\mathbf{1}[\\hat y=y]\\) 选择 \\(r\\)，近似「成功轨迹上的最大似然」。这与后来的拒绝采样 SFT、RFT 是同一家族，差别是外环迭代与合理化补失败。没有负例梯度：做错的理由若不经合理化，不会被显式压低，只是不出现。这与 RL 里对错样本都更新不同。</p><p><span class="marginnote">直觉类比：STaR 像老师只把做对的作业贴到墙上当范文，做错的本子直接退回（除非被合理化救回），从不批注「你错在哪一步」。所以模型只被告诉「该这样写」，从未被告诉「别那样写」——RL 则相反，对错误样本会给出压低其概率的负梯度。</span></p><p><span class="marginnote">外环从基座重微调，是为了对抗「本轮数据被上一策略的错误模式污染后还在同一权重上接着学」。代价是算力随轮数重置。持续训练单一检查点是另一种实现，原文不采用。</span></p><h3 id="机会水平会污染理由" tabindex="-1">机会水平会污染理由 <a class="header-anchor" href="#机会水平会污染理由" aria-label="Permalink to &quot;机会水平会污染理由&quot;">​</a></h3><p>CQA 五选一，随机 20%，浅启发式约 30%。答对不等于理由对。作者承认常识题上理由质量只能个案看，不像算术能对齐标准草稿纸。这是 STaR 在分类任务上的结构性噪声，也解释了为何后来数学 RL 更爱可解析的最终数字，而不是五选一。</p><p><span class="marginnote">数字感受一下：五选一的题闭眼乱猜也有约 20% 正确率，一万道题里就有约两千道「答对」。这些题的理由哪怕全是胡编，也会因为最终答案碰巧对而被收进训练集。初学者容易以为「答对了说明推理对了」，在生成式任务上大致成立，在选择题上这个推断会系统性地漏进坏样本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>STaR 需要可自动核对的 \\(y\\)。开放写作没有这个过滤器。基座太弱则外环起不来。二分类任务正例污染重，原文列为未解决问题。合理化可能写入「从答案反推的事后诸葛」，表面连贯、并非模型在无 \\(y\\) 时会走的搜索；下一轮 few-shot 生成若仍依赖这种风格，会与真实解题分布错位。GPT-J 的 GSM8K 10.7% 只说明 2022 年 6B 上的自举存在性，不能与 2025 年的长链 RL 比绝对分。</p><p>与 RL 的关系：STaR 是迭代过滤 SFT，没有优势、没有 KL 惩罚、没有在线奖励模型。Quiet-STaR 去掉 \\(y\\)，改用未来词似然；R1 用规则奖励在线更新。三条都「从自己的生成里学」，监督密度与是否改策略梯度不同。</p><p><span class="marginnote">「可比 30 倍大的 GPT-3」仅针对 CQA 直接微调的 73% 这一格，不是跨任务、跨协议的普遍结论。GSM8K 上 GPT-J 的 STaR 远未接近后来的专用数学模型。</span></p><h3 id="何时不必上-star" tabindex="-1">何时不必上 STaR <a class="header-anchor" href="#何时不必上-star" aria-label="Permalink to &quot;何时不必上 STaR&quot;">​</a></h3><p>已有大规模正确长链（蒸馏轨迹），一次 SFT 就够，不必多外环。有可验证奖励与采样预算，GRPO 一类能用负例。没有标准答案，换 Quiet-STaR 或偏好学习。基座 few-shot 已在随机水平，先做预训练或更大模型，不要空转外环。</p>',16)),(t(),r(l,null,{default:e(()=>[A(o,{id:"mermaid-116",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E7%AD%94%E6%A1%88%20y%20%E8%83%BD%E8%87%AA%E5%8A%A8%E6%A0%B8%E5%AF%B9%E5%90%97%3F%22%7D%0A%20%20Q%20--%3E%7C%E4%B8%8D%E8%83%BD%7C%20ALT%5B%22%E6%8D%A2%E5%81%8F%E5%A5%BD%E5%AD%A6%E4%B9%A0%E6%88%96%20Quiet-STaR%22%5D%0A%20%20Q%20--%3E%7C%E8%83%BD%7C%20FEW%7B%22%E5%9F%BA%E5%BA%A7%20few-shot%20%E9%AB%98%E4%BA%8E%E9%9A%8F%E6%9C%BA%3F%22%7D%0A%20%20FEW%20--%3E%7C%E5%90%A6%7C%20PRE%5B%22%E5%85%88%E6%8D%A2%E6%9B%B4%E5%BC%BA%E5%9F%BA%E5%BA%A7%E6%88%96%E7%BB%A7%E7%BB%AD%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20FEW%20--%3E%7C%E6%98%AF%7C%20CHAIN%7B%22%E5%B7%B2%E6%9C%89%E5%A4%A7%E8%A7%84%E6%A8%A1%E6%AD%A3%E7%A1%AE%E9%95%BF%E9%93%BE%3F%22%7D%0A%20%20CHAIN%20--%3E%7C%E6%9C%89%7C%20SFT%5B%22%E4%B8%80%E6%AC%A1%20SFT%20%E8%92%B8%E9%A6%8F%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20CHAIN%20--%3E%7C%E6%97%A0%7C%20VER%7B%22%E6%9C%89%E5%8F%AF%E9%AA%8C%E8%AF%81%E5%A5%96%E5%8A%B1%E4%B8%8E%E9%87%87%E6%A0%B7%E9%A2%84%E7%AE%97%3F%22%7D%0A%20%20VER%20--%3E%7C%E6%9C%89%7C%20RL%5B%22%E7%94%A8%20GRPO%20%E4%B8%80%E7%B1%BB%E5%9C%A8%E7%BA%BF%20RL%22%5D%0A%20%20VER%20--%3E%7C%E6%97%A0%7C%20STAR%5B%22%E4%B8%8A%20STaR%20%E5%A4%96%E7%8E%AF%E8%87%AA%E4%B8%BE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>STaR 用少量理由示范，在带标签题上自生成理由，按最终答案过滤后微调，外环迭代。</li><li>合理化：失败题看到 \\(y\\) 再写理由，入库时去掉 \\(y\\)，用于打破「只会已经会的题」。</li><li>GPT-J 上 CQA 72.5%、算术 89.5%、GSM8K 10.7%，对照为直接微调与 few-shot CoT。</li><li>高温度不能替代合理化；机会水平任务会混进坏理由。</li><li>它是过滤式自举 SFT，不是策略梯度；后续 Quiet-STaR 与长链 RL 是不同监督。</li><li>出处：Zelikman, Wu, Mu, Goodman，<em>STaR: Bootstrapping Reasoning With Reasoning</em>，NeurIPS 2022，arXiv:2203.14465。</li></ul>',2))])}const f=i(h,[["render",p]]);export{u as __pageData,f as default};
